/**
 * Element text layout (#340): a deterministic text-width model and the word
 * wrapping that keeps an element's label, `[technology]` and description inside
 * its shape.
 *
 * Why a width table and not the browser: the extension host has no DOM, the
 * goldens are byte-compared, and the same SVG must come out on every machine.
 * Widths therefore come from per-character advance tables measured once in
 * Chrome Canary (src/render/textMetricsData.ts, regenerated by
 * scripts/generate-text-metrics.cjs) for the three font stacks the themes use.
 *
 * Host and webview share this code: the webview embeds these functions verbatim
 * (see TEXT_LAYOUT_CLIENT_FUNCTIONS and previewClientScript), so live edits wrap
 * exactly as the host renders. Every function here is therefore self-contained:
 * no imports, no module constants, metrics passed in as an argument. A parity
 * test runs the embedded copy in its own realm against the host.
 *
 * Compatibility rule: when every field fits on one line, the caller draws it
 * exactly as before (same `<text>`, same box size). Wrapping, growth and the cap
 * apply only to text that does not fit.
 */
import {
    TEXT_METRIC_CJK,
    TEXT_METRIC_EMOJI,
    TEXT_METRIC_RANGES,
    TEXT_METRIC_WIDTHS,
} from './textMetricsData';

/** Width tables and fallbacks the model reads; JSON-serialisable for the webview. */
export interface TextMetrics {
    readonly ranges: ReadonlyArray<readonly [number, number]>;
    readonly widths: Readonly<Record<string, ReadonlyArray<number>>>;
    /** Widest measured colour emoji, thousandths of an em. */
    readonly emoji: number;
    /** Widest measured CJK ideograph, thousandths of an em. */
    readonly cjk: number;
}

export const TEXT_METRICS: TextMetrics = {
    ranges: TEXT_METRIC_RANGES,
    widths: TEXT_METRIC_WIDTHS,
    emoji: TEXT_METRIC_EMOJI,
    cjk: TEXT_METRIC_CJK,
};

/** The C4 type name printed in an element's type line (#348); not localised. */
export function elementTypeLabel(type: string): string | undefined {
    switch (type) {
        case 'Person': return 'Person';
        case 'SoftwareSystem': return 'Software System';
        case 'Container': return 'Container';
        case 'Component': return 'Component';
        case 'DeploymentNode': return 'Deployment Node';
        default: return undefined;
    }
}

export type ElementTextField = 'label' | 'technology' | 'description';

/** Geometry and text of one element, as the renderer, layout and webview know it. */
export interface ElementTextInput {
    readonly x: number;
    readonly y: number;
    readonly width: number;
    readonly height: number;
    /** Icon top centre, text below (Person, sprite, or shape with an icon). */
    readonly iconLayout: boolean;
    /** Database cylinder outline: the caps are not usable for text. */
    readonly cylinder: boolean;
    /**
     * The shape's text-safe inner box (#323: person body, bucket, folder, web
     * browser, terminal), absolute. When set, text is laid out in this box
     * instead of the bounding box; the box's chrome (`height` less this
     * box's height) is added to the required height.
     */
    readonly textBox?: { readonly x: number; readonly y: number; readonly width: number; readonly height: number };
    /** The theme's CSS font-family list. */
    readonly fontFamily: string;
    readonly label?: string;
    readonly technology?: string;
    /**
     * The element's C4 type name, e.g. `Container`. When set, the second line reads
     * `[Type]` or `[Type: technology]` instead of `[technology]` (#348). It is the
     * same field, measured and wrapped by the same code (cap 2). Absent: as before.
     */
    readonly typeLabel?: string;
    readonly description?: string;
    /**
     * Deployment notation label row (#326): the fields are drawn left-aligned at
     * the box's bottom left, 10 px in plus `iconSlot` (the icon's room), the last
     * baseline 10 px above the bottom edge, on 16 px lines: name bold 14 px (cap
     * 2), type line and description 12 px upright (caps 2 and 3). `maxLines`
     * caps the row at the lines its node reserved: a live edit longer than that
     * keeps at least the name, then the type line, then the description, each
     * cut with an ellipsis, and drops what does not fit, so the row never grows
     * over the node's children before Save lays it out again. Absent: the
     * centred layout, unchanged.
     */
    readonly labelRow?: { readonly iconSlot: number; readonly maxLines?: number };
}

/** One drawn text field: a single line, or wrapped lines. */
export interface ElementTextBlock {
    readonly field: ElementTextField;
    /** The text as drawn when it fits (unchanged source text), else the wrapped lines. */
    readonly lines: string[];
    /** Baselines, one per line. */
    readonly ys: number[];
    readonly x: number;
    readonly fontSize: number;
    readonly bold: boolean;
    readonly italic: boolean;
    /** True when the field did not fit on one line. */
    readonly wrapped: boolean;
    /** True when lines were cut at the cap and the last ends with an ellipsis. */
    readonly truncated: boolean;
    /** The full text (with brackets for technology), for a tooltip when truncated. */
    readonly full: string;
    /** `start` for a left-aligned label row (#326); absent: centred. */
    readonly anchor?: 'start';
}

export interface ElementTextLayout {
    readonly blocks: ElementTextBlock[];
    /** True when any field wrapped; false means the pre-#340 single-line drawing. */
    readonly wrapped: boolean;
    /**
     * Box height that holds every wrapped line within the caps. Equals the input
     * height when nothing wrapped. Layout grows a box to max(standard, this).
     */
    readonly requiredHeight: number;
}

/**
 * Model variant for a font-family list and weight/style: `sans`, `serif` or
 * `mono`, with `-bold` or `-italic`. The first family the model knows decides;
 * an unknown list falls back to `sans`.
 */
export function textMetricVariant(fontFamily: string, bold: boolean, italic: boolean): string {
    const families = String(fontFamily || '').split(',').map(f => f.trim().replace(/^["']|["']$/g, '').toLowerCase());
    let base = 'sans';
    for (const family of families) {
        if (family === 'arial' || family === 'helvetica' || family === 'helvetica neue' || family === 'liberation sans' || family === 'sans-serif') {
            base = 'sans';
            break;
        }
        if (family === 'georgia' || family === 'times' || family === 'times new roman' || family === 'serif') {
            base = 'serif';
            break;
        }
        if (family === 'consolas' || family === 'menlo' || family === 'monaco' || family === 'courier' || family === 'courier new' || family === 'monospace') {
            base = 'mono';
            break;
        }
    }
    return base + (bold ? '-bold' : italic ? '-italic' : '');
}

/** Advance of one code point in thousandths of an em. */
export function textAdvanceEm(codePoint: number, variant: string, metrics: TextMetrics): number {
    const cp = codePoint;
    // Zero width: combining marks, joiners, variation selectors, skin-tone modifiers, tags.
    if ((cp >= 0x300 && cp <= 0x36f) || (cp >= 0x1ab0 && cp <= 0x1aff) || (cp >= 0x1dc0 && cp <= 0x1dff)
        || (cp >= 0x20d0 && cp <= 0x20ff) || (cp >= 0xfe20 && cp <= 0xfe2f) || (cp >= 0x200b && cp <= 0x200f)
        || (cp >= 0x2060 && cp <= 0x2064) || (cp >= 0xfe00 && cp <= 0xfe0f) || cp === 0xfeff
        || (cp >= 0x1f3fb && cp <= 0x1f3ff) || (cp >= 0xe0000 && cp <= 0xe01ef)) {
        return 0;
    }
    const table = metrics.widths[variant] || metrics.widths.sans;
    // Control characters (tab, newline) draw as a space once whitespace collapses.
    if (cp < 0x20) {
        return table[0];
    }
    let offset = 0;
    for (const range of metrics.ranges) {
        if (cp >= range[0] && cp <= range[1]) {
            return table[offset + cp - range[0]];
        }
        offset += range[1] - range[0] + 1;
    }
    // East Asian wide and fullwidth forms.
    if ((cp >= 0x1100 && cp <= 0x115f) || (cp >= 0x2e80 && cp <= 0x303e) || (cp >= 0x3041 && cp <= 0x33ff)
        || (cp >= 0x3400 && cp <= 0x4dbf) || (cp >= 0x4e00 && cp <= 0x9fff) || (cp >= 0xa000 && cp <= 0xa4cf)
        || (cp >= 0xac00 && cp <= 0xd7a3) || (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0xfe30 && cp <= 0xfe4f)
        || (cp >= 0xff00 && cp <= 0xff60) || (cp >= 0xffe0 && cp <= 0xffe6) || (cp >= 0x20000 && cp <= 0x3fffd)) {
        return metrics.cjk;
    }
    // Emoji and pictographs: at least 1.2 em, wider than the measured macOS glyph
    // because other platforms' emoji fonts are not measured.
    if ((cp >= 0x1f000 && cp <= 0x1faff) || (cp >= 0x2600 && cp <= 0x27bf) || (cp >= 0x2b00 && cp <= 0x2bff)) {
        return Math.max(metrics.emoji, 1200);
    }
    // Not in the tables, by Unicode general category: marks and format
    // characters draw nothing; a space separator gets an en space (every space
    // separator Unicode defines is measured in the tables, so this is only for
    // future additions); any other character the width of "M", wider than most
    // letters of most scripts.
    const ch = String.fromCodePoint(cp);
    if (/^[\p{Mn}\p{Me}\p{Cf}]$/u.test(ch)) {
        return 0;
    }
    if (/^\p{Zs}$/u.test(ch)) {
        return 500;
    }
    return table[0x4d - 0x20];
}

/** Estimated drawn width of `text` in px. */
export function measureTextPx(text: string, fontSize: number, variant: string, metrics: TextMetrics): number {
    // Layout, the renderer and the webview measure the same strings repeatedly:
    // cache the em total per variant and string on the metrics object (bounded).
    const store = metrics as unknown as { __emCache?: Map<string, number> };
    if (!(store.__emCache instanceof Map) || store.__emCache.size > 20000) {
        // Not enumerable: the metrics are serialised into the webview.
        Object.defineProperty(store, '__emCache', { value: new Map(), writable: true, configurable: true, enumerable: false });
    }
    const key = variant + '\u0000' + text;
    const cache = store.__emCache as Map<string, number>;
    let total = cache.get(key);
    if (total === undefined) {
        total = 0;
        for (const ch of String(text)) {
            total += textAdvanceEm(ch.codePointAt(0) as number, variant, metrics);
        }
        cache.set(key, total);
    }
    return (total / 1000) * fontSize;
}

/**
 * Whether a field is drawn unchanged, on one line, exactly as before #340.
 *
 * Only text the model measures exactly is ever wrapped: every character must
 * have a measured width in the tables (Latin with Extended-A, -B, Additional
 * and IPA, Greek, Cyrillic, general punctuation and spaces) and must not be a
 * bidirectional control. Such text stays on one line when its width fits
 * `innerWidth`, the box less its text padding. Any other text (right-to-left
 * scripts, Thai, Devanagari, Chinese, Japanese, Korean in any normalisation
 * form, emoji and emoji sequences, symbols such as check marks or card suits,
 * combining marks outside the tables, anything unknown) is drawn exactly as
 * before, however long (#340 review 6; measured wrapping of other scripts is a
 * follow-up, #459).
 */
export function textFitsBox(text: string, fontSize: number, variant: string, metrics: TextMetrics, innerWidth: number): boolean {
    if (!isExactlyMeasured(text, variant, metrics)) {
        return true;
    }
    return measureTextPx(text, fontSize, variant, metrics) <= innerWidth;
}

/** Every character of `text` has a measured width and none is a bidirectional control. */
export function isExactlyMeasured(text: string, variant: string, metrics: TextMetrics): boolean {
    const table = metrics.widths[variant] || metrics.widths.sans;
    for (const ch of String(text)) {
        const cp = ch.codePointAt(0) as number;
        if (cp === 0x200e || cp === 0x200f || (cp >= 0x202a && cp <= 0x202e) || (cp >= 0x2066 && cp <= 0x2069)) {
            return false;
        }
        if (cp < 0x20) {
            continue;
        }
        let measured = false;
        let offset = 0;
        for (const range of metrics.ranges) {
            if (cp >= range[0] && cp <= range[1]) {
                measured = table[offset + cp - range[0]] !== undefined;
                break;
            }
            offset += range[1] - range[0] + 1;
        }
        if (!measured) {
            return false;
        }
    }
    return true;
}

/**
 * Word-wrap `text` to `maxWidth` px. Whitespace runs collapse to one space (as
 * SVG draws them); there is no forced line break. A word wider than the line
 * breaks after `/ - . _ , ; : ? & = + | \ ) ] }`, between East Asian wide
 * characters, or, failing those, between characters; zero-width marks stay with
 * the character before them. More than `maxLines` lines: the last kept line ends
 * with an ellipsis and `truncated` is true.
 */
export function wrapTextLines(
    text: string,
    maxWidth: number,
    fontSize: number,
    variant: string,
    metrics: TextMetrics,
    maxLines: number,
): { lines: string[]; truncated: boolean } {
    // Collapse whitespace as SVG draws it (no xml:space): runs of space, tab,
    // CR, LF and FF become one space and the ends are trimmed. Non-breaking and
    // other Unicode spaces are drawn as they are and are not break points.
    // Measured in Chrome Canary: U+00A0, U+202F and U+3000 are drawn and never
    // collapse; U+200B and U+FEFF draw at zero width and never collapse. So only
    // these five characters are collapsed or trimmed (never String.trim or \s).
    const normalized = String(text).replace(/[ \t\n\r\f]+/g, ' ').replace(/^ | $/g, '');
    if (normalized === '') {
        return { lines: [], truncated: false };
    }
    const width = (s: string): number => measureTextPx(s, fontSize, variant, metrics);
    const breakAfter = '/-._,;:?&=+|\\)]}';
    const isWide = (s: string): boolean => {
        const cp = s.codePointAt(0) as number;
        return textAdvanceEm(cp, variant, metrics) === metrics.cjk && cp >= 0x1100;
    };
    // Split a token wider than the line into pieces that each fit.
    const breakToken = (token: string): string[] => {
        const units: string[] = [];
        for (const ch of token) {
            const cp = ch.codePointAt(0) as number;
            // Zero-width characters and combining marks (Thai vowels and tones,
            // Devanagari vowel signs and virama) stay with the character before.
            if (units.length > 0 && (textAdvanceEm(cp, variant, metrics) === 0 || /^\p{M}$/u.test(ch))) {
                units[units.length - 1] += ch;
            } else {
                units.push(ch);
            }
        }
        // A break is allowed after unit i when it is a separator or an East
        // Asian wide character, or when unit i + 1 is wide.
        const breakAfterAt = (units: string[], i: number): boolean =>
            breakAfter.indexOf(units[i]) >= 0 || isWide(units[i]) || (i + 1 < units.length && isWide(units[i + 1]));
        const pieces: string[] = [];
        let current: string[] = [];
        for (const unit of units) {
            current.push(unit);
            // Invariant: before the push, `current` fitted (or was one glyph
            // wider than the line). Cut until it fits again, rechecking what is
            // left after every cut, so no piece is wider than the line except a
            // single glyph that is wider on its own.
            while (current.length > 1 && width(current.join('')) > maxWidth) {
                let cut = -1;
                for (let i = current.length - 2; i >= 0; i--) {
                    if (breakAfterAt(current, i) && width(current.slice(0, i + 1).join('')) <= maxWidth) {
                        cut = i;
                        break;
                    }
                }
                if (cut < 0) {
                    cut = current.length - 2; // no separator fits: break between characters
                }
                pieces.push(current.slice(0, cut + 1).join(''));
                current = current.slice(cut + 1);
            }
        }
        if (current.length > 0) {
            pieces.push(current.join(''));
        }
        return pieces;
    };
    const lines: string[] = [];
    let line = '';
    for (const token of normalized.split(' ')) {
        const candidate = line ? line + ' ' + token : token;
        if (width(candidate) <= maxWidth) {
            line = candidate;
            continue;
        }
        if (line) {
            lines.push(line);
            line = '';
        }
        if (width(token) <= maxWidth) {
            line = token;
        } else {
            const pieces = breakToken(token);
            for (let i = 0; i < pieces.length - 1; i++) {
                lines.push(pieces[i]);
            }
            line = pieces[pieces.length - 1];
        }
    }
    if (line) {
        lines.push(line);
    }
    const cap = Math.max(1, Math.floor(maxLines));
    if (lines.length <= cap) {
        return { lines, truncated: false };
    }
    const kept = lines.slice(0, cap);
    const ellipsis = '\u2026';
    const base = kept[cap - 1];
    const candidate = base + ' ' + lines[cap];
    const chars = Array.from(candidate);
    while (chars.length > 0 && width(chars.join('').replace(/[ \t\n\r\f]+$/, '') + ellipsis) > maxWidth) {
        chars.pop();
    }
    let cut = chars.join('');
    // End on a whole word when the cut falls inside a word of the next line.
    if (cut.length > base.length && cut.length < candidate.length && candidate.charAt(cut.length) !== ' ') {
        const space = cut.lastIndexOf(' ');
        if (space >= base.length) {
            cut = cut.slice(0, space);
        }
    }
    kept[cap - 1] = cut.replace(/[ \t\n\r\f]+$/, '') + ellipsis;
    return { lines: kept, truncated: true };
}

/**
 * Lay out an element's text inside its shape.
 *
 * Text area: the box less 8 px each side; an icon layout starts 50 px down
 * (icon and gap); a cylinder loses 24 px at the top (lid) and, as text is
 * centred, the same at the bottom. Fonts: label bold 14 px, technology italic
 * and description 12 px on 16 px lines (11 px on 15 px lines under an icon), as
 * before.
 *
 * A field wraps only when it is made entirely of exactly measured characters
 * and its estimated width is wider than the inner width (the box less 8 px each
 * side); every other field is drawn exactly as before (textFitsBox). A field that wraps is broken into lines whose
 * estimated width plus a 3 % safety margin fits the text area (the measured
 * model error in Chrome Canary is under 2 %).
 *
 * Caps: label 3 lines, technology 2, description 6; beyond, the last line ends
 * with an ellipsis. If the box is too short for the wrapped lines (a live edit
 * before Save), lines are cut from the description, then the technology, then
 * the label, each keeping at least one.
 */
export function layoutElementText(input: ElementTextInput, metrics: TextMetrics): ElementTextLayout {
    if (input.labelRow) {
        // Deployment notation label row (#326): bottom left, beside the icon.
        // Numbers mirror src/render/deploymentNotation.ts (inlined: the webview
        // embeds this function verbatim).
        const slot = input.labelRow.iconSlot > 0 ? input.labelRow.iconSlot : 0;
        const left = input.x + 10 + slot;
        const avail = Math.max(1, input.width - 20 - slot);
        const rowFields: Array<{ field: ElementTextField; text: string; size: number; bold: boolean; cap: number }> = [];
        if (input.label) {
            rowFields.push({ field: 'label', text: input.label, size: 14, bold: true, cap: 2 });
        }
        const rowType = input.typeLabel
            ? (input.technology ? input.typeLabel + ': ' + input.technology : input.typeLabel)
            : input.technology;
        if (rowType) {
            rowFields.push({ field: 'technology', text: '[' + rowType + ']', size: 12, bold: false, cap: 2 });
        }
        if (input.description) {
            rowFields.push({ field: 'description', text: input.description, size: 12, bold: false, cap: 3 });
        }
        let rowWrapped = false;
        const laid = rowFields.map(f => {
            const variant = textMetricVariant(input.fontFamily, f.bold, false);
            const drawn = f.text.replace(/[ \t\n\r\f]+/g, ' ').replace(/^ | $/g, '');
            if (textFitsBox(drawn, f.size, variant, metrics, avail)) {
                return { f, lines: [f.text], wrapped: false, truncated: false };
            }
            rowWrapped = true;
            const result = wrapTextLines(f.text, avail / 1.03, f.size, variant, metrics, f.cap);
            return { f, lines: result.lines.length > 0 ? result.lines : [f.text], wrapped: true, truncated: result.truncated };
        });
        let rowLines = laid;
        const capacity = input.labelRow.maxLines !== undefined && input.labelRow.maxLines > 0 ? Math.floor(input.labelRow.maxLines) : 0;
        if (capacity > 0 && laid.reduce((sum, l) => sum + l.lines.length, 0) > capacity) {
            // One line each in field order while room is left, then the rest in the same order.
            const allot = laid.map(() => 0);
            let budget = capacity;
            for (let i = 0; i < laid.length && budget > 0; i++) { allot[i] = 1; budget--; }
            for (let i = 0; i < laid.length && budget > 0; i++) {
                const more = Math.min(laid[i].lines.length - allot[i], budget);
                allot[i] += more;
                budget -= more;
            }
            rowLines = [];
            laid.forEach((l, i) => {
                if (allot[i] === 0) { return; }
                if (allot[i] >= l.lines.length) { rowLines.push(l); return; }
                const variant = textMetricVariant(input.fontFamily, l.f.bold, false);
                const cut = wrapTextLines(l.f.text, avail / 1.03, l.f.size, variant, metrics, allot[i]);
                rowLines.push({ f: l.f, lines: cut.lines.length > 0 ? cut.lines : [l.f.text], wrapped: true, truncated: cut.truncated });
                rowWrapped = true;
            });
        }
        const count = rowLines.reduce((sum, l) => sum + l.lines.length, 0);
        let baseline = input.y + input.height - 10 - 16 * Math.max(0, count - 1);
        const rowBlocks: ElementTextBlock[] = rowLines.map(l => {
            const ys = l.lines.map(() => {
                const y = baseline;
                baseline += 16;
                return y;
            });
            return {
                field: l.f.field,
                lines: l.lines,
                ys,
                x: left,
                fontSize: l.f.size,
                bold: l.f.bold,
                italic: false,
                wrapped: l.wrapped,
                truncated: l.truncated,
                full: l.f.text,
                anchor: 'start',
            };
        });
        // A leaf node holds its label row (and icon) with 8 px above it.
        const rowHeight = Math.max(10 + 16 * Math.max(0, count - 1) + 13, slot > 0 ? 40 : 0);
        return { blocks: rowBlocks, wrapped: rowWrapped, requiredHeight: Math.max(input.height, Math.ceil(rowHeight + 8)) };
    }
    const padX = 8;
    const padY = 8;
    const margin = 1.03;
    const iconOffset = 50;
    const capInset = 24;
    const icon = !!input.iconLayout;
    const titleSize = 14;
    const smallSize = icon ? 11 : 12;
    const lineHeight = icon ? 15 : 16;
    const baselineAdjust = icon ? -2 : 0;
    const box = input.textBox || input;
    const chrome = input.height - box.height;
    const areaY = icon ? box.y + iconOffset : box.y;
    const areaHeight = icon ? box.height - iconOffset : box.height;
    const insets = 2 * padY + (input.cylinder ? 2 * capInset : 0);
    const innerWidth = box.width - 2 * padX;
    const cx = box.x + box.width / 2;

    const fields: Array<{ field: ElementTextField; text: string; size: number; bold: boolean; italic: boolean; cap: number }> = [];
    if (input.label) {
        fields.push({ field: 'label', text: input.label, size: titleSize, bold: true, italic: false, cap: 3 });
    }
    const typeLine = input.typeLabel
        ? (input.technology ? input.typeLabel + ': ' + input.technology : input.typeLabel)
        : input.technology;
    if (typeLine) {
        fields.push({ field: 'technology', text: '[' + typeLine + ']', size: smallSize, bold: false, italic: true, cap: 2 });
    }
    const description = input.description || '';
    if (description) {
        fields.push({ field: 'description', text: description, size: smallSize, bold: false, italic: false, cap: 6 });
    }

    let anyWrapped = false;
    const wrappedFields = fields.map(f => {
        const variant = textMetricVariant(input.fontFamily, f.bold, f.italic);
        // Wrap only text that runs past the shape's edge: text inside the box,
        // however close to its edge, keeps the pre-#340 drawing byte for byte.
        // Measured as SVG draws it, with whitespace runs collapsed and the ends
        // trimmed, so spaces the browser does not draw cannot trigger a wrap.
        // Only exactly measured text wraps, and it wraps when it does not fit the
        // inner width (the box less the text padding); other text is drawn as
        // before (textFitsBox).
        const drawn = f.text.replace(/[ \t\n\r\f]+/g, ' ').replace(/^ | $/g, '');
        const fits = textFitsBox(drawn, f.size, variant, metrics, innerWidth);
        if (fits) {
            return { ...f, variant, lines: [f.text], wrapped: false, truncated: false };
        }
        anyWrapped = true;
        const result = wrapTextLines(f.text, innerWidth / margin, f.size, variant, metrics, f.cap);
        const lines = result.lines.length > 0 ? result.lines : [f.text];
        return { ...f, variant, lines, wrapped: true, truncated: result.truncated };
    });

    let requiredHeight = input.height;
    // A named shape's text box can be too short for even unwrapped lines, so
    // its height is always checked (#323); other shapes keep the pre-#340 rule.
    if (anyWrapped || input.textBox) {
        const total = wrappedFields.reduce((sum, f) => sum + f.lines.length, 0);
        requiredHeight = Math.ceil(total * lineHeight + insets + (icon ? iconOffset : 0) + chrome);
        // Fit the box as drawn: cut lines when it is shorter than required.
        const capacity = Math.floor((areaHeight - insets) / lineHeight);
        let excess = total - Math.max(capacity, wrappedFields.length);
        for (const field of ['description', 'technology', 'label'] as ElementTextField[]) {
            const f = wrappedFields.find(w => w.field === field);
            if (!f || excess <= 0) { continue; }
            const keep = Math.max(1, f.lines.length - excess);
            if (keep < f.lines.length) {
                excess -= f.lines.length - keep;
                const cut = wrapTextLines(f.text, innerWidth / margin, f.size, f.variant, metrics, keep);
                f.lines = cut.lines;
                f.truncated = cut.truncated;
            }
        }
    }

    const totalLines = wrappedFields.reduce((sum, f) => sum + f.lines.length, 0);
    let currentY = areaY + (areaHeight - totalLines * lineHeight) / 2 + lineHeight + baselineAdjust;
    const blocks: ElementTextBlock[] = wrappedFields.map(f => {
        const ys = f.lines.map(() => {
            const y = currentY;
            currentY += lineHeight;
            return y;
        });
        return {
            field: f.field,
            lines: f.lines,
            ys,
            x: cx,
            fontSize: f.size,
            bold: f.bold,
            italic: f.italic,
            wrapped: f.wrapped,
            truncated: f.truncated,
            full: f.text,
        };
    });
    return { blocks, wrapped: anyWrapped, requiredHeight };
}

/**
 * SVG markup for laid-out element text, one `<text data-field>` per field joined
 * by the renderer's indentation. A field that fits is the pre-#340 single-line
 * `<text>`; a wrapped field holds one `<tspan>` per line, and a truncated one
 * carries its full text in a `<title>` tooltip. The webview inserts the same
 * markup on live edits.
 */
export function elementTextMarkup(layout: ElementTextLayout, fill: string, fontFamily: string): string {
    // Characters XML cannot carry become U+FFFD, as in escapeXml (#362, SVG-5); inlined because
    // the webview embeds this function verbatim.
    const esc = (text: string): string => String(text)
        // eslint-disable-next-line no-control-regex
        .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\ufffe\uffff]|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g, '\ufffd')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');
    return layout.blocks.map(block => {
        const face = block.bold ? ' font-weight="bold"' : block.italic ? ' font-style="italic"' : '';
        const open = '<text data-field="' + block.field + '" x="' + block.x.toFixed(2) + '" y="' + block.ys[0].toFixed(2)
            + '" fill="' + fill + '" text-anchor="' + (block.anchor === 'start' ? 'start' : 'middle') + '" font-size="' + block.fontSize + '" font-family="' + fontFamily + '"' + face + '>';
        if (!block.wrapped) {
            return open + esc(block.lines[0]) + '</text>';
        }
        const tooltip = block.truncated ? '<title>' + esc(block.full) + '</title>' : '';
        const lines = block.lines.map((line, i) => '<tspan x="' + block.x.toFixed(2) + '" y="' + block.ys[i].toFixed(2) + '">' + esc(line) + '</tspan>').join('');
        return open + tooltip + lines + '</text>';
    }).join('\n    ');
}

/** The functions the webview embeds verbatim, in dependency order. */
export const TEXT_LAYOUT_CLIENT_FUNCTIONS: ReadonlyArray<(...args: never[]) => unknown> = [
    textMetricVariant,
    textAdvanceEm,
    measureTextPx,
    isExactlyMeasured,
    textFitsBox,
    wrapTextLines,
    layoutElementText,
    elementTextMarkup,
];
